+/// The pairing invite the QR code and "Copy invite" carry: the host's
+/// page at the address a device reaches it on, with the code, the key
+/// and the id in the fragment. A fragment is never sent in a request,
+/// so the code reaches only the page's script, which compares the key
+/// with `/info` first. `address` is used only while the port listens on
+/// the network; otherwise the port answers this Mac alone, and the URL
+/// says so by naming loopback.
+#[must_use]
+pub fn invite_url(
+    identity: &Identity,
+    window: &PairingWindow,
+    address: Option<IpAddr>,
+    port: u16,
+) -> String {
+    let ip = address
+        .filter(|_| identity.listen.lan)
+        .unwrap_or(IpAddr::V4(Ipv4Addr::LOCALHOST));
+    format!(
+        "https://{}/#code={}&key={}&id={}",
+        SocketAddr::new(ip, port),
+        window.code,
+        identity.spki_sha256,
+        identity.server_id
+    )
+}
