1	// Switchboard's page on the remote port. It speaks the protocol a
2	// native client speaks (docs/remote-client.md) over the page's own
3	// origin: the host keeps the token in an HttpOnly cookie this script
4	// never sees, so what the page keeps is public (the host's id, key hash
5	// and name), and every text from the host reaches the page through
6	// `textContent` only, never as markup.
7	'use strict';
8	
9	// Every path the page calls, in one table so a test on the host can
10	// check that each one is served. `{id}` is a project or session id.
11	const API = {
12	  info: '/api/v1/info',
13	  pair: '/api/v1/pair',
14	  me: '/api/v1/me',
15	  projects: '/api/v1/projects',
16	  sessions: '/api/v1/projects/{id}/sessions',
17	  waiting: '/api/v1/waiting',
18	  lastResponse: '/api/v1/sessions/{id}/last-response',
19	  screen: '/api/v1/sessions/{id}/screen',
20	  send: '/api/v1/sessions/{id}/send',
21	  events: '/api/v1/events',
22	};
23	
24	const STORE_KEY = 'switchboard';
25	// The poll carries the page on every browser; when the events socket
26	// is up, a change arrives at once and the poll only backs it up.
27	const POLL_MS = 3000;
28	const POLL_WITH_SOCKET_MS = 20000;
29	const RETRY_FIRST_MS = 5000;
30	const RETRY_LAST_MS = 60000;
31	
32	// --- pure parts, tested with `node --test web/app.test.js`
33	
34	function apiPath(name, id) {
35	  return API[name].replace('{id}', encodeURIComponent(id || ''));
36	}
37	
38	// The invite's code, key and server id from the URL's fragment, or
39	// null when any is missing.
40	function parseFragment(hash) {
41	  const values = {};
42	  for (const pair of String(hash || '').replace(/^#/, '').split('&')) {
43	    const at = pair.indexOf('=');
44	    if (at < 1) continue;
45	    try {
46	      values[decodeURIComponent(pair.slice(0, at))] = decodeURIComponent(pair.slice(at + 1));
47	    } catch (_) {
48	      return null;
49	    }
50	  }
51	  if (!values.code || !values.key || !values.id) return null;
52	  return { code: values.code, key: values.key, id: values.id };
53	}
54	
55	// "Safari on iPhone": what the host's device list shows for this
56	// browser. An iPad asking for the desktop site says Macintosh, and only
57	// its touch points tell it from a Mac.
58	function deviceName(ua, touchPoints) {
59	  let browser = 'Safari';
60	  if (/Edg(e|iOS|A)?\//.test(ua)) browser = 'Edge';
61	  else if (/(Chrome|CriOS)\//.test(ua)) browser = 'Chrome';
62	  else if (/(Firefox|FxiOS)\//.test(ua)) browser = 'Firefox';
63	  let device = null;
64	  if (/iPhone/.test(ua)) device = 'iPhone';
65	  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
66	  else if (/Android/.test(ua)) device = 'Android';
67	  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
68	  else if (/Windows/.test(ua)) device = 'Windows';
69	  else if (/Linux/.test(ua)) device = 'Linux';
70	  return device ? browser + ' on ' + device : 'Browser';
71	}
72	
73	// What a 401 means. The host answers a revoked token and an unknown one
74	// alike, so the page asks `/info`, which anyone may read: the same id
75	// and key as when it paired say this device was removed; another says
76	// the host's identity changed; no answer says the host is out of reach.
77	function unauthorizedState(stored, info) {
78	  if (!stored) return 'unpaired';
79	  if (!info) return 'unreachable';
80	  if (info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256) {
81	    return 'removed';
82	  }
83	  return 'changed';
84	}
85	
86	const STATE_TEXT = {
87	  unpaired: 'Not paired. On the Mac, open Remote devices, allow pairing, and scan its code.',
88	  unreachable: "Can't reach the host.",
89	  removed: 'This device was removed on the host. Pair again.',
90	  changed: "This host's identity changed. Pair again.",
91	};
92	
93	const PAIR_ERRORS = {
94	  pairing_closed: 'Pairing is not open on the Mac. Open it again and scan the new code.',
95	  wrong_code: 'The code did not match. Scan the code the Mac shows now.',
96	  wrong_key: 'This is not the Switchboard whose code was scanned. Nothing was paired.',
97	  rate_limited: 'Too many attempts. Wait a minute and scan again.',
98	};
99	
100	// Whether a reply should replace what the page holds (§4.4): a reply
101	// from another epoch (the host restarted) always does; within one, an
102	// older revision never does.
103	function isNewer(held, reply) {
104	  if (!held) return true;
105	  if (held.epoch !== reply.epoch) return true;
106	  return reply.revision >= held.revision;
107	}
108	
109	// Whether the host moved since `held` was read.
110	function moved(held, reply) {
111	  return !held || held.epoch !== reply.epoch || held.revision !== reply.revision;
112	}
113	
114	// Projects with a waiting session first, waiting sessions first within
115	// each; otherwise the host's order.
116	function orderGroups(projects, sessionsByProject) {
117	  const waitingFirst = (items, isWaiting) =>
118	    items
119	      .map((item, at) => ({ item, at }))
120	      .sort((a, b) => Number(isWaiting(b.item)) - Number(isWaiting(a.item)) || a.at - b.at)
121	      .map((x) => x.item);
122	  const groups = projects.map((project) => ({
123	    project,
124	    sessions: waitingFirst(sessionsByProject[project.id] || [], (s) => s.waiting),
125	  }));
126	  return waitingFirst(groups, (g) => g.sessions.some((s) => s.waiting));
127	}
128	
129	// "5 min ago", from milliseconds since the epoch.
130	function since(ms, now) {
131	  if (!ms) return '';
132	  const secs = Math.max(0, Math.round((now - ms) / 1000));
133	  if (secs < 60) return 'just now';
134	  if (secs < 3600) return Math.floor(secs / 60) + ' min ago';
135	  if (secs < 86400) return Math.floor(secs / 3600) + ' h ago';
136	  return Math.floor(secs / 86400) + ' d ago';
137	}
138	
139	// An operation id: the key that makes a retried send run once.
140	function opId(random) {
141	  const bytes = new Uint8Array(16);
142	  random(bytes);
143	  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
144	}
145	
146	if (typeof module !== 'undefined' && module.exports) {
147	  module.exports = {
148	    API,
149	    apiPath,
150	    parseFragment,
151	    deviceName,
152	    unauthorizedState,
153	    isNewer,
154	    moved,
155	    orderGroups,
156	    since,
157	    opId,
158	  };
159	}
160	
161	// --- the page
162	
163	if (typeof document !== 'undefined') {
164	  const state = {
165	    stored: null,
166	    me: null,
167	    list: null,
168	    open: null,
169	    pending: null,
170	    view: null,
171	    stopped: false,
172	    socketUp: false,
173	    retryMs: RETRY_FIRST_MS,
174	    pollTimer: null,
175	    refreshing: null,
176	    again: false,
177	  };
178	
179	  const el = (tag, className, text) => {
180	    const node = document.createElement(tag);
181	    if (className) node.className = className;
182	    if (text !== undefined && text !== null) node.textContent = text;
183	    return node;
184	  };
185	  const main = () => document.getElementById('main');
186	
187	  const loadStored = () => {
188	    try {
189	      return JSON.parse(localStorage.getItem(STORE_KEY) || 'null');
190	    } catch (_) {
191	      return null;
192	    }
193	  };
194	  const saveStored = (info) => {
195	    const value = {
196	      server_id: info.server_id,
197	      spki_sha256: info.spki_sha256,
198	      server_name: info.server_name,
199	    };
200	    state.stored = value;
201	    try {
202	      localStorage.setItem(STORE_KEY, JSON.stringify(value));
203	    } catch (_) {
204	      // A private window may refuse storage; the cookie still pairs.
205	    }
206	  };
207	
208	  const showMessage = (text) => {
209	    state.view = null;
210	    main().replaceChildren(el('p', 'notice', text));
211	  };
212	
213	  const errorCode = (json) => (json && json.error && json.error.code) || '';
214	  const errorText = (json) => (json && json.error && json.error.message) || 'The host refused.';
215	
216	  // One call on the page's own origin; the browser adds the cookie.
217	  // Any 401 but the pairing's own runs the `/info` inference.
218	  const call = async (name, id, init) => {
219	    let result;
220	    try {
221	      const response = await fetch(apiPath(name, id), {
222	        credentials: 'same-origin',
223	        cache: 'no-store',
224	        ...init,
225	      });
226	      let json = null;
227	      try {
228	        json = await response.json();
229	      } catch (_) {
230	        json = null;
231	      }
232	      result = { status: response.status, json };
233	    } catch (_) {
234	      result = { status: 0, json: null };
235	    }
236	    if (result.status === 401 && name !== 'pair') await unauthorized();
237	    return result;
238	  };
239	  const post = (name, id, body) =>
240	    call(name, id, {
241	      method: 'POST',
242	      headers: { 'Content-Type': 'application/json' },
243	      body: JSON.stringify(body),
244	    });
245	
246	  const unauthorized = async () => {
247	    state.stopped = true;
248	    let info = null;
249	    if (state.stored) {
250	      const reply = await call('info');
251	      info = reply.status === 200 && reply.json ? reply.json.body : null;
252	    }
253	    document.getElementById('header').hidden = true;
254	    showMessage(STATE_TEXT[unauthorizedState(state.stored, info)]);
255	  };
256	
257	  const pairWith = async (invite) => {
258	    showMessage('Pairing…');
259	    const info = await call('info');
260	    if (info.status !== 200 || !info.json) return showMessage(STATE_TEXT.unreachable);
261	    const body = info.json.body;
262	    if (body.spki_sha256 !== invite.key || body.server_id !== invite.id) {
263	      return showMessage(
264	        'This address is a different Switchboard than the code was for. Nothing was sent.',
265	      );
266	    }
267	    const reply = await post('pair', null, {
268	      code: invite.code,
269	      spki_sha256: invite.key,
270	      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
271	      transport: 'cookie',
272	    });
273	    if (reply.status !== 200) {
274	      return showMessage(PAIR_ERRORS[errorCode(reply.json)] || errorText(reply.json));
275	    }
276	    saveStored(body);
277	    return start();
278	  };
279	
280	  const readMe = async () => {
281	    const me = await call('me');
282	    if (me.status !== 200 || !me.json) return false;
283	    state.me = me.json.body;
284	    document.getElementById('host').textContent = state.me.server_name || 'Switchboard';
285	    document.getElementById('scope').textContent =
286	      state.me.scope === 'control' ? 'can reply' : 'read only';
287	    document.getElementById('header').hidden = false;
288	    return true;
289	  };
290	
291	  const start = async () => {
292	    state.stopped = false;
293	    if (!(await readMe())) {
294	      if (!state.stopped) showMessage(STATE_TEXT.unreachable);
295	      return;
296	    }
297	    if (!state.stored || state.stored.server_id !== state.me.server_id) {
298	      const info = await call('info');
299	      if (info.status === 200 && info.json) saveStored(info.json.body);
300	    }
301	    await refresh();
302	    schedule();
303	    connectSocket();
304	  };
305	
306	  // --- reading
307	
308	  const readList = async () => {
309	    const projects = await call('projects');
310	    if (projects.status !== 200 || !projects.json) return;
311	    const envelope = { epoch: projects.json.epoch, revision: projects.json.revision };
312	    if (!isNewer(state.list, envelope)) return;
313	    const sessionsByProject = {};
314	    for (const project of projects.json.body.projects) {
315	      const reply = await call('sessions', project.id);
316	      if (reply.status === 200 && reply.json) {
317	        sessionsByProject[project.id] = reply.json.body.sessions;
318	      }
319	    }
320	    state.list = {
321	      ...envelope,
322	      groups: orderGroups(projects.json.body.projects, sessionsByProject),
323	    };
324	  };
325	
326	  const findSession = (id) => {
327	    for (const group of (state.list && state.list.groups) || []) {
328	      const found = group.sessions.find((s) => s.id === id);
329	      if (found) return found;
330	    }
331	    return null;
332	  };
333	
334	  // A Claude Code session shows its last response; anything else, the
335	  // screen.
336	  const readOpen = async () => {
337	    const open = state.open;
338	    const session = findSession(open.id);
339	    const name = session && session.kind === 'claude' ? 'lastResponse' : 'screen';
340	    const reply = await call(name, open.id);
341	    if (state.open !== open) return;
342	    if (reply.status === 200 && reply.json) {
343	      if (isNewer(open.held, reply.json)) {
344	        open.held = { epoch: reply.json.epoch, revision: reply.json.revision };
345	        open.text = reply.json.body.text || '';
346	        open.note = null;
347	      }
348	    } else if (reply.status !== 0) {
349	      open.note = errorText(reply.json);
350	    }
351	  };
352	
353	  // Refetch the list and the open session. Calls that arrive while one
354	  // runs fold into one more pass after it.
355	  const refresh = async () => {
356	    if (state.stopped) return;
357	    if (state.refreshing) {
358	      state.again = true;
359	      return state.refreshing;
360	    }
361	    state.refreshing = (async () => {
362	      do {
363	        state.again = false;
364	        await readList();
365	        if (state.stopped) return;
366	        if (state.open) await readOpen();
367	        if (state.stopped) return;
368	        render();
369	      } while (state.again);
370	    })();
371	    try {
372	      await state.refreshing;
373	    } finally {
374	      state.refreshing = null;
375	    }
376	  };
377	
378	  const poll = async () => {
379	    if (state.stopped || document.hidden) return;
380	    const reply = await call('waiting');
381	    if (reply.status === 200 && reply.json && moved(state.list, reply.json)) await refresh();
382	  };
383	
384	  const schedule = () => {
385	    clearTimeout(state.pollTimer);
386	    if (state.stopped) return;
387	    state.pollTimer = setTimeout(
388	      async () => {
389	        await poll();
390	        schedule();
391	      },
392	      state.socketUp ? POLL_WITH_SOCKET_MS : POLL_MS,
393	    );
394	  };
395	
396	  // The events socket: a change arrives at once while it is up. It
397	  // carries the cookie; a browser that will not open it (Safari over a
398	  // certificate it does not trust) leaves the page on the poll.
399	  const connectSocket = () => {
400	    if (state.stopped || typeof WebSocket === 'undefined') return;
401	    let socket;
402	    try {
403	      socket = new WebSocket('wss://' + location.host + API.events);
404	    } catch (_) {
405	      retrySocket();
406	      return;
407	    }
408	    socket.onopen = () => {
409	      state.socketUp = true;
410	      state.retryMs = RETRY_FIRST_MS;
411	      schedule();
412	    };
413	    socket.onmessage = (event) => {
414	      let frame;
415	      try {
416	        frame = JSON.parse(event.data);
417	      } catch (_) {
418	        return;
419	      }
420	      if (frame.type === 'changed' || frame.type === 'removed') refresh();
421	    };
422	    // An error is always followed by a close, and `resync_required` by
423	    // the host's close.
424	    socket.onclose = () => {
425	      state.socketUp = false;
426	      if (state.stopped) return;
427	      schedule();
428	      refresh();
429	      retrySocket();
430	    };
431	  };
432	
433	  const retrySocket = () => {
434	    setTimeout(connectSocket, state.retryMs);
435	    state.retryMs = Math.min(state.retryMs * 2, RETRY_LAST_MS);
436	  };
437	
438	  // --- drawing
439	
440	  const render = () => {
441	    if (state.stopped) return;
442	    if (state.open) renderSession();
443	    else renderList();
444	  };
445	
446	  const describe = (session, now) => {
447	    const parts = [session.kind, session.card, since(session.last_activity_ms, now)];
448	    return parts.filter(Boolean).join(' · ');
449	  };
450	
451	  const renderList = () => {
452	    state.view = null;
453	    const now = Date.now();
454	    const nodes = [];
455	    const groups = (state.list && state.list.groups) || [];
456	    for (const group of groups) {
457	      if (!group.sessions.length) continue;
458	      nodes.push(el('h2', null, group.project.name));
459	      for (const session of group.sessions) {
460	        const row = el('button', session.waiting ? 'row waiting' : 'row');
461	        row.type = 'button';
462	        if (session.waiting) {
463	          const words = session.waiting_reason
464	            ? 'Waiting on you: ' + session.waiting_reason
465	            : 'Waiting on you';
466	          row.append(el('div', 'waiting-word', words));
467	        }
468	        row.append(el('div', 'name', session.name));
469	        row.append(el('div', 'meta', describe(session, now)));
470	        row.addEventListener('click', () => openSession(session.id));
471	        nodes.push(row);
472	      }
473	    }
474	    if (!nodes.length) nodes.push(el('p', 'meta', 'No sessions on this host.'));
475	    main().replaceChildren(...nodes);
476	  };
477	
478	  const openSession = async (id) => {
479	    state.open = { id, held: null, text: null, note: null };
480	    state.pending = null;
481	    render();
482	    await readOpen();
483	    render();
484	  };
485	
486	  const closeSession = () => {
487	    state.open = null;
488	    state.pending = null;
489	    render();
490	  };
491	
492	  // The session view is built once per session and updated in place,
493	  // so a refresh never takes the reply box's text or focus.
494	  const renderSession = () => {
495	    const open = state.open;
496	    if (!state.view || state.view.id !== open.id) {
497	      const back = el('button', 'link', '‹ Sessions');
498	      back.type = 'button';
499	      back.addEventListener('click', closeSession);
500	      state.view = {
501	        id: open.id,
502	        title: el('h2'),
503	        waiting: el('div', 'waiting-word'),
504	        meta: el('div', 'meta'),
505	        note: el('p', 'meta'),
506	        content: el('pre', 'content'),
507	        compose: el('div'),
508	        mode: null,
509	      };
510	      const v = state.view;
511	      main().replaceChildren(back, v.title, v.waiting, v.meta, v.note, v.content, v.compose);
512	    }
513	    const v = state.view;
514	    const session = findSession(open.id);
515	    v.title.textContent = session ? session.name : 'Session';
516	    v.waiting.textContent =
517	      session && session.waiting
518	        ? session.waiting_reason
519	          ? 'Waiting on you: ' + session.waiting_reason
520	          : 'Waiting on you'
521	        : '';
522	    v.meta.textContent = session ? describe(session, Date.now()) : 'Not on the host any more.';
523	    v.note.textContent = open.note || '';
524	    v.content.textContent = open.text === null ? 'Loading…' : open.text || '(nothing yet)';
525	    renderCompose(session);
526	  };
527	
528	  const renderCompose = (session) => {
529	    const v = state.view;
530	    const control = state.me && state.me.scope === 'control';
531	    const refusal = session ? session.prompt_refusal : 'The session is gone.';
532	    let mode = 'read';
533	    if (control) mode = refusal ? 'refused:' + refusal : 'box';
534	    if (v.mode === mode) return;
535	    v.mode = mode;
536	    if (mode === 'read') {
537	      v.compose.replaceChildren(el('p', 'meta', 'This device reads only.'));
538	      return;
539	    }
540	    if (mode !== 'box') {
541	      v.compose.replaceChildren(el('p', 'meta', refusal));
542	      return;
543	    }
544	    const box = el('textarea');
545	    box.setAttribute('aria-label', 'Reply');
546	    const button = el('button', 'action', 'Send');
547	    button.type = 'button';
548	    const status = el('p', 'meta');
549	    button.addEventListener('click', () => send(box, status));
550	    v.compose.replaceChildren(box, button, status);
551	  };
552	
553	  const send = async (box, status) => {
554	    const text = box.value.trim();
555	    if (!text) return;
556	    const id = state.open.id;
557	    // A retry of the same text after a lost reply keeps its op, so the
558	    // host answers it from its log rather than typing it twice.
559	    if (!state.pending || state.pending.id !== id || state.pending.text !== text) {
560	      state.pending = { id, text, op: opId((b) => crypto.getRandomValues(b)) };
561	    }
562	    status.textContent = 'Sending…';
563	    const reply = await post('send', id, { op: state.pending.op, text });
564	    if (reply.status === 200) {
565	      state.pending = null;
566	      box.value = '';
567	      status.textContent = 'Sent.';
568	      refresh();
569	    } else if (reply.status === 0) {
570	      status.textContent = 'No answer. Send again repeats the same message once.';
571	    } else if (reply.status === 403 && errorCode(reply.json) === 'scope') {
572	      await readMe();
573	      if (state.view) state.view.mode = null;
574	      render();
575	    } else if (reply.status !== 401) {
576	      state.pending = null;
577	      status.textContent = errorText(reply.json);
578	    }
579	  };
580	
581	  document.addEventListener('visibilitychange', () => {
582	    if (!document.hidden) poll();
583	  });
584	
585	  const boot = () => {
586	    state.stored = loadStored();
587	    const invite = parseFragment(location.hash);
588	    // The code leaves the address bar before anything else runs.
589	    if (location.hash) history.replaceState(null, '', location.pathname);
590	    if (invite) return pairWith(invite);
591	    return start();
592	  };
593	
594	  boot();
595	}
