// Switchboard's page on the remote port. It speaks the protocol a
// native client speaks (docs/remote-client.md) over the page's own
// origin: the host keeps the token in an HttpOnly cookie this script
// never sees, so what the page keeps is public (the host's id, key hash
// and name), and every text from the host reaches the page through
// `textContent` only, never as markup.
'use strict';

// Every path the page calls, in one table so a test on the host can
// check that each one is served. `{id}` is a project or session id.
const API = {
  info: '/api/v1/info',
  pair: '/api/v1/pair',
  me: '/api/v1/me',
  projects: '/api/v1/projects',
  sessions: '/api/v1/projects/{id}/sessions',
  waiting: '/api/v1/waiting',
  lastResponse: '/api/v1/sessions/{id}/last-response',
  screen: '/api/v1/sessions/{id}/screen',
  send: '/api/v1/sessions/{id}/send',
  events: '/api/v1/events',
};

const STORE_KEY = 'switchboard';
// The poll carries the page on every browser; when the events socket
// is up, a change arrives at once and the poll only backs it up.
const POLL_MS = 3000;
const POLL_WITH_SOCKET_MS = 20000;
const RETRY_FIRST_MS = 5000;
const RETRY_LAST_MS = 60000;

// --- pure parts, tested with `node --test web/app.test.js`

function apiPath(name, id) {
  return API[name].replace('{id}', encodeURIComponent(id || ''));
}

// The invite's code, key and server id from the URL's fragment, or
// null when any is missing.
function parseFragment(hash) {
  const values = {};
  for (const pair of String(hash || '').replace(/^#/, '').split('&')) {
    const at = pair.indexOf('=');
    if (at < 1) continue;
    try {
      values[decodeURIComponent(pair.slice(0, at))] = decodeURIComponent(pair.slice(at + 1));
    } catch (_) {
      return null;
    }
  }
  if (!values.code || !values.key || !values.id) return null;
  return { code: values.code, key: values.key, id: values.id };
}

// "Safari on iPhone": what the host's device list shows for this
// browser. An iPad asking for the desktop site says Macintosh, and only
// its touch points tell it from a Mac.
function deviceName(ua, touchPoints) {
  let browser = 'Safari';
  if (/Edg(e|iOS|A)?\//.test(ua)) browser = 'Edge';
  else if (/(Chrome|CriOS)\//.test(ua)) browser = 'Chrome';
  else if (/(Firefox|FxiOS)\//.test(ua)) browser = 'Firefox';
  let device = null;
  if (/iPhone/.test(ua)) device = 'iPhone';
  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
  else if (/Android/.test(ua)) device = 'Android';
  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
  else if (/Windows/.test(ua)) device = 'Windows';
  else if (/Linux/.test(ua)) device = 'Linux';
  return device ? browser + ' on ' + device : 'Browser';
}

// What a 401 means. The host answers a revoked token and an unknown one
// alike, so the page asks `/info`, which anyone may read: the same id
// and key as when it paired say this device was removed; another says
// the host's identity changed; no answer says the host is out of reach.
function unauthorizedState(stored, info) {
  if (!stored) return 'unpaired';
  if (!info) return 'unreachable';
  if (info.server_id === stored.server_id && info.spki_sha256 === stored.spki_sha256) {
    return 'removed';
  }
  return 'changed';
}

const STATE_TEXT = {
  unpaired: 'Not paired. On the Mac, open Remote devices, allow pairing, and scan its code.',
  unreachable: "Can't reach the host.",
  removed: 'This device was removed on the host. Pair again.',
  changed: "This host's identity changed. Pair again.",
};

const PAIR_ERRORS = {
  pairing_closed: 'Pairing is not open on the Mac. Open it again and scan the new code.',
  wrong_code: 'The code did not match. Scan the code the Mac shows now.',
  wrong_key: 'This is not the Switchboard whose code was scanned. Nothing was paired.',
  rate_limited: 'Too many attempts. Wait a minute and scan again.',
};

// Whether a reply should replace what the page holds (§4.4): a reply
// from another epoch (the host restarted) always does; within one, an
// older revision never does.
function isNewer(held, reply) {
  if (!held) return true;
  if (held.epoch !== reply.epoch) return true;
  return reply.revision >= held.revision;
}

// Whether the host moved since `held` was read.
function moved(held, reply) {
  return !held || held.epoch !== reply.epoch || held.revision !== reply.revision;
}

// Projects with a waiting session first, waiting sessions first within
// each; otherwise the host's order.
function orderGroups(projects, sessionsByProject) {
  const waitingFirst = (items, isWaiting) =>
    items
      .map((item, at) => ({ item, at }))
      .sort((a, b) => Number(isWaiting(b.item)) - Number(isWaiting(a.item)) || a.at - b.at)
      .map((x) => x.item);
  const groups = projects.map((project) => ({
    project,
    sessions: waitingFirst(sessionsByProject[project.id] || [], (s) => s.waiting),
  }));
  return waitingFirst(groups, (g) => g.sessions.some((s) => s.waiting));
}

// "5 min ago", from milliseconds since the epoch.
function since(ms, now) {
  if (!ms) return '';
  const secs = Math.max(0, Math.round((now - ms) / 1000));
  if (secs < 60) return 'just now';
  if (secs < 3600) return Math.floor(secs / 60) + ' min ago';
  if (secs < 86400) return Math.floor(secs / 3600) + ' h ago';
  return Math.floor(secs / 86400) + ' d ago';
}

// An operation id: the key that makes a retried send run once.
function opId(random) {
  const bytes = new Uint8Array(16);
  random(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    API,
    apiPath,
    parseFragment,
    deviceName,
    unauthorizedState,
    isNewer,
    moved,
    orderGroups,
    since,
    opId,
  };
}

// --- the page

if (typeof document !== 'undefined') {
  const state = {
    stored: null,
    me: null,
    list: null,
    open: null,
    pending: null,
    view: null,
    stopped: false,
    socketUp: false,
    retryMs: RETRY_FIRST_MS,
    pollTimer: null,
    refreshing: null,
    again: false,
  };

  const el = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  };
  const main = () => document.getElementById('main');

  const loadStored = () => {
    try {
      return JSON.parse(localStorage.getItem(STORE_KEY) || 'null');
    } catch (_) {
      return null;
    }
  };
  const saveStored = (info) => {
    const value = {
      server_id: info.server_id,
      spki_sha256: info.spki_sha256,
      server_name: info.server_name,
    };
    state.stored = value;
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(value));
    } catch (_) {
      // A private window may refuse storage; the cookie still pairs.
    }
  };

  const showMessage = (text) => {
    state.view = null;
    main().replaceChildren(el('p', 'notice', text));
  };

  const errorCode = (json) => (json && json.error && json.error.code) || '';
  const errorText = (json) => (json && json.error && json.error.message) || 'The host refused.';

  // One call on the page's own origin; the browser adds the cookie.
  // Any 401 but the pairing's own runs the `/info` inference.
  const call = async (name, id, init) => {
    let result;
    try {
      const response = await fetch(apiPath(name, id), {
        credentials: 'same-origin',
        cache: 'no-store',
        ...init,
      });
      let json = null;
      try {
        json = await response.json();
      } catch (_) {
        json = null;
      }
      result = { status: response.status, json };
    } catch (_) {
      result = { status: 0, json: null };
    }
    if (result.status === 401 && name !== 'pair') await unauthorized();
    return result;
  };
  const post = (name, id, body) =>
    call(name, id, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });

  const unauthorized = async () => {
    state.stopped = true;
    let info = null;
    if (state.stored) {
      const reply = await call('info');
      info = reply.status === 200 && reply.json ? reply.json.body : null;
    }
    document.getElementById('header').hidden = true;
    showMessage(STATE_TEXT[unauthorizedState(state.stored, info)]);
  };

  const pairWith = async (invite) => {
    showMessage('Pairing…');
    const info = await call('info');
    if (info.status !== 200 || !info.json) return showMessage(STATE_TEXT.unreachable);
    const body = info.json.body;
    if (body.spki_sha256 !== invite.key || body.server_id !== invite.id) {
      return showMessage(
        'This address is a different Switchboard than the code was for. Nothing was sent.',
      );
    }
    const reply = await post('pair', null, {
      code: invite.code,
      spki_sha256: invite.key,
      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
      transport: 'cookie',
    });
    if (reply.status !== 200) {
      return showMessage(PAIR_ERRORS[errorCode(reply.json)] || errorText(reply.json));
    }
    saveStored(body);
    return start();
  };

  const readMe = async () => {
    const me = await call('me');
    if (me.status !== 200 || !me.json) return false;
    state.me = me.json.body;
    document.getElementById('host').textContent = state.me.server_name || 'Switchboard';
    document.getElementById('scope').textContent =
      state.me.scope === 'control' ? 'can reply' : 'read only';
    document.getElementById('header').hidden = false;
    return true;
  };

  const start = async () => {
    state.stopped = false;
    if (!(await readMe())) {
      if (!state.stopped) showMessage(STATE_TEXT.unreachable);
      return;
    }
    if (!state.stored || state.stored.server_id !== state.me.server_id) {
      const info = await call('info');
      if (info.status === 200 && info.json) saveStored(info.json.body);
    }
    await refresh();
    schedule();
    connectSocket();
  };

  // --- reading

  const readList = async () => {
    const projects = await call('projects');
    if (projects.status !== 200 || !projects.json) return;
    const envelope = { epoch: projects.json.epoch, revision: projects.json.revision };
    if (!isNewer(state.list, envelope)) return;
    const sessionsByProject = {};
    for (const project of projects.json.body.projects) {
      const reply = await call('sessions', project.id);
      if (reply.status === 200 && reply.json) {
        sessionsByProject[project.id] = reply.json.body.sessions;
      }
    }
    state.list = {
      ...envelope,
      groups: orderGroups(projects.json.body.projects, sessionsByProject),
    };
  };

  const findSession = (id) => {
    for (const group of (state.list && state.list.groups) || []) {
      const found = group.sessions.find((s) => s.id === id);
      if (found) return found;
    }
    return null;
  };

  // A Claude Code session shows its last response; anything else, the
  // screen.
  const readOpen = async () => {
    const open = state.open;
    const session = findSession(open.id);
    const name = session && session.kind === 'claude' ? 'lastResponse' : 'screen';
    const reply = await call(name, open.id);
    if (state.open !== open) return;
    if (reply.status === 200 && reply.json) {
      if (isNewer(open.held, reply.json)) {
        open.held = { epoch: reply.json.epoch, revision: reply.json.revision };
        open.text = reply.json.body.text || '';
        open.note = null;
      }
    } else if (reply.status !== 0) {
      open.note = errorText(reply.json);
    }
  };

  // Refetch the list and the open session. Calls that arrive while one
  // runs fold into one more pass after it.
  const refresh = async () => {
    if (state.stopped) return;
    if (state.refreshing) {
      state.again = true;
      return state.refreshing;
    }
    state.refreshing = (async () => {
      do {
        state.again = false;
        await readList();
        if (state.stopped) return;
        if (state.open) await readOpen();
        if (state.stopped) return;
        render();
      } while (state.again);
    })();
    try {
      await state.refreshing;
    } finally {
      state.refreshing = null;
    }
  };

  const poll = async () => {
    if (state.stopped || document.hidden) return;
    const reply = await call('waiting');
    if (reply.status === 200 && reply.json && moved(state.list, reply.json)) await refresh();
  };

  const schedule = () => {
    clearTimeout(state.pollTimer);
    if (state.stopped) return;
    state.pollTimer = setTimeout(
      async () => {
        await poll();
        schedule();
      },
      state.socketUp ? POLL_WITH_SOCKET_MS : POLL_MS,
    );
  };

  // The events socket: a change arrives at once while it is up. It
  // carries the cookie; a browser that will not open it (Safari over a
  // certificate it does not trust) leaves the page on the poll.
  const connectSocket = () => {
    if (state.stopped || typeof WebSocket === 'undefined') return;
    let socket;
    try {
      socket = new WebSocket('wss://' + location.host + API.events);
    } catch (_) {
      retrySocket();
      return;
    }
    socket.onopen = () => {
      state.socketUp = true;
      state.retryMs = RETRY_FIRST_MS;
      schedule();
    };
    socket.onmessage = (event) => {
      let frame;
      try {
        frame = JSON.parse(event.data);
      } catch (_) {
        return;
      }
      if (frame.type === 'changed' || frame.type === 'removed') refresh();
    };
    // An error is always followed by a close, and `resync_required` by
    // the host's close.
    socket.onclose = () => {
      state.socketUp = false;
      if (state.stopped) return;
      schedule();
      refresh();
      retrySocket();
    };
  };

  const retrySocket = () => {
    setTimeout(connectSocket, state.retryMs);
    state.retryMs = Math.min(state.retryMs * 2, RETRY_LAST_MS);
  };

  // --- drawing

  const render = () => {
    if (state.stopped) return;
    if (state.open) renderSession();
    else renderList();
  };

  const describe = (session, now) => {
    const parts = [session.kind, session.card, since(session.last_activity_ms, now)];
    return parts.filter(Boolean).join(' · ');
  };

  const renderList = () => {
    state.view = null;
    const now = Date.now();
    const nodes = [];
    const groups = (state.list && state.list.groups) || [];
    for (const group of groups) {
      if (!group.sessions.length) continue;
      nodes.push(el('h2', null, group.project.name));
      for (const session of group.sessions) {
        const row = el('button', session.waiting ? 'row waiting' : 'row');
        row.type = 'button';
        if (session.waiting) {
          const words = session.waiting_reason
            ? 'Waiting on you: ' + session.waiting_reason
            : 'Waiting on you';
          row.append(el('div', 'waiting-word', words));
        }
        row.append(el('div', 'name', session.name));
        row.append(el('div', 'meta', describe(session, now)));
        row.addEventListener('click', () => openSession(session.id));
        nodes.push(row);
      }
    }
    if (!nodes.length) nodes.push(el('p', 'meta', 'No sessions on this host.'));
    main().replaceChildren(...nodes);
  };

  const openSession = async (id) => {
    state.open = { id, held: null, text: null, note: null };
    state.pending = null;
    render();
    await readOpen();
    render();
  };

  const closeSession = () => {
    state.open = null;
    state.pending = null;
    render();
  };

  // The session view is built once per session and updated in place,
  // so a refresh never takes the reply box's text or focus.
  const renderSession = () => {
    const open = state.open;
    if (!state.view || state.view.id !== open.id) {
      const back = el('button', 'link', '‹ Sessions');
      back.type = 'button';
      back.addEventListener('click', closeSession);
      state.view = {
        id: open.id,
        title: el('h2'),
        waiting: el('div', 'waiting-word'),
        meta: el('div', 'meta'),
        note: el('p', 'meta'),
        content: el('pre', 'content'),
        compose: el('div'),
        mode: null,
      };
      const v = state.view;
      main().replaceChildren(back, v.title, v.waiting, v.meta, v.note, v.content, v.compose);
    }
    const v = state.view;
    const session = findSession(open.id);
    v.title.textContent = session ? session.name : 'Session';
    v.waiting.textContent =
      session && session.waiting
        ? session.waiting_reason
          ? 'Waiting on you: ' + session.waiting_reason
          : 'Waiting on you'
        : '';
    v.meta.textContent = session ? describe(session, Date.now()) : 'Not on the host any more.';
    v.note.textContent = open.note || '';
    v.content.textContent = open.text === null ? 'Loading…' : open.text || '(nothing yet)';
    renderCompose(session);
  };

  const renderCompose = (session) => {
    const v = state.view;
    const control = state.me && state.me.scope === 'control';
    const refusal = session ? session.prompt_refusal : 'The session is gone.';
    let mode = 'read';
    if (control) mode = refusal ? 'refused:' + refusal : 'box';
    if (v.mode === mode) return;
    v.mode = mode;
    if (mode === 'read') {
      v.compose.replaceChildren(el('p', 'meta', 'This device reads only.'));
      return;
    }
    if (mode !== 'box') {
      v.compose.replaceChildren(el('p', 'meta', refusal));
      return;
    }
    const box = el('textarea');
    box.setAttribute('aria-label', 'Reply');
    const button = el('button', 'action', 'Send');
    button.type = 'button';
    const status = el('p', 'meta');
    button.addEventListener('click', () => send(box, status));
    v.compose.replaceChildren(box, button, status);
  };

  const send = async (box, status) => {
    const text = box.value.trim();
    if (!text) return;
    const id = state.open.id;
    // A retry of the same text after a lost reply keeps its op, so the
    // host answers it from its log rather than typing it twice.
    if (!state.pending || state.pending.id !== id || state.pending.text !== text) {
      state.pending = { id, text, op: opId((b) => crypto.getRandomValues(b)) };
    }
    status.textContent = 'Sending…';
    const reply = await post('send', id, { op: state.pending.op, text });
    if (reply.status === 200) {
      state.pending = null;
      box.value = '';
      status.textContent = 'Sent.';
      refresh();
    } else if (reply.status === 0) {
      status.textContent = 'No answer. Send again repeats the same message once.';
    } else if (reply.status === 403 && errorCode(reply.json) === 'scope') {
      await readMe();
      if (state.view) state.view.mode = null;
      render();
    } else if (reply.status !== 401) {
      state.pending = null;
      status.textContent = errorText(reply.json);
    }
  };

  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) poll();
  });

  const boot = () => {
    state.stored = loadStored();
    const invite = parseFragment(location.hash);
    // The code leaves the address bar before anything else runs.
    if (location.hash) history.replaceState(null, '', location.pathname);
    if (invite) return pairWith(invite);
    return start();
  };

  boot();
}

